        public static string Svg(string faClass, string sizeClass)
        {
            string key = (faClass ?? "").Replace("fas ", "").Replace("far ", "").Replace("fab ", "").Replace("fa-", "");
            return SvgFromName(key, sizeClass);
        }

        public static string SvgFromName(string name, string sizeClass)
        {
            string path;
            if (name == null || !_paths.TryGetValue(name, out path)) return "";
            return "<svg xmlns='http://www.w3.org/2000/svg' fill='none' viewBox='0 0 24 24' stroke-width='1.5' stroke='currentColor' class='" + sizeClass + " inline-block align-middle'>" + path + "</svg>";
        }
